/** Width variants generated by `npm run optimize-images` (`{base}-{w}w.webp`). */
export type ResponsiveWidths = readonly number[]

export const WIDTHS = {
  banner: [480, 768, 1200, 1920],
  logo: [120, 200, 400],
  homeFeature: [480, 768, 1024, 1280],
  reviewBadge: [280, 400, 560],
  clientLogo: [120, 200],
} as const

export const SIZES = {
  banner: '100vw',
  logo: '(max-width: 480px) 42vw, 200px',
  homeFeature: '(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 640px',
  reviewBadge: '(max-width: 640px) min(100vw, 400px), 320px',
  clientLogo: '120px',
} as const

export function buildWidthSrcSet(
  basePath: string,
  ext: 'webp' | 'jpg' | 'jpeg' | 'png',
  widths: readonly number[],
): string {
  return widths.map((w) => `${basePath}-${w}w.${ext} ${w}w`).join(', ')
}

/** Default `src` when using `srcset` (reasonable mid-size). */
export function defaultSrcFromSet(
  basePath: string,
  ext: string,
  widths: readonly number[],
  prefer = 768,
): string {
  const pick = widths.includes(prefer)
    ? prefer
    : widths[widths.length - 1] ?? widths[0] ?? prefer
  return `${basePath}-${pick}w.${ext}`
}
